"""Read-only lifecycle diagnosis of the finite private profile documented in task.py."""
import json
import time


def diagnose(admin, s3, bucket, context):
    def read(*argv):
        row = admin(*argv)
        if row['returncode'] != 0:
            raise RuntimeError(row['stderr'])
        return json.loads(row['stdout'])

    policy = read('lc', 'get', '--bucket', bucket)
    progress = read('lc', 'list')
    sdk_policy = s3.get_bucket_lifecycle_configuration(Bucket=bucket)
    sdk_policy.pop('ResponseMetadata', None)
    versions = []
    args = {'Bucket': bucket, 'MaxKeys': 3}
    while True:
        page = s3.list_object_versions(**args)
        for group in ('Versions', 'DeleteMarkers'):
            for v in page.get(group, []):
                item = {'kind': group, 'key': v['Key'], 'version_id': v['VersionId'],
                        'is_latest': v['IsLatest'], 'last_modified': v['LastModified'].isoformat()}
                if group == 'Versions':
                    item['size'] = v['Size']
                versions.append(item)
        if not page['IsTruncated']:
            break
        args.update(KeyMarker=page['NextKeyMarker'], VersionIdMarker=page['NextVersionIdMarker'])
    versions.sort(key=lambda x: (x['key'], x['version_id'], x['kind']))
    from datetime import datetime
    def age(v):
        return context['now_epoch'] - datetime.fromisoformat(v['last_modified']).timestamp()

    rules = sdk_policy['Rules']
    def matches(v, field, days_field):
        for rule in rules:
            prefix = rule.get('Filter', {}).get('Prefix', rule.get('Prefix', ''))
            days = rule.get(field, {}).get(days_field)
            if rule['Status'] == 'Enabled' and v['key'].startswith(prefix) and days is not None:
                if age(v) >= days * context['day_seconds']:
                    return True
        return False
    current = [v for v in versions if v['kind'] == 'Versions' and v['is_latest'] and v['key'].startswith(context['due_prefix'])]
    # In this controlled fixture noncurrent history is older than its newer head
    # by more than one scaled day; use the native current head timestamp.
    old = [v for v in versions if v['kind'] == 'Versions' and not v['is_latest'] and v['key'].startswith(context['history_prefix'])]
    current_matching = sum(matches(v, 'Expiration', 'Days') for v in current)
    old_matching = 0
    for v in old:
        head = next(x for x in versions if x['key'] == v['key'] and x['is_latest'])
        if matches(head, 'NoncurrentVersionExpiration', 'NoncurrentDays'):
            old_matching += 1
    unmatched = len(current) - current_matching
    measurement = context['measurement']
    if unmatched:
        diagnosis = 'policy_mismatch'
    elif context['known_paused'] and current_matching + old_matching:
        diagnosis = 'scheduler_paused'
    elif measurement is not None and measurement['actions'] > 0:
        diagnosis = 'controlled_progress'
    else:
        diagnosis = 'insufficient_evidence'
    error = admin('lc', 'get', '--bucket', context['missing_bucket'])
    if error['returncode'] == 0:
        raise ValueError('expected real missing-bucket read error')
    return {
        'policy': policy, 'sdk_policy': sdk_policy, 'progress': progress,
        'versions': versions,
        'current_candidates': len(current), 'matching_current': current_matching,
        'matching_noncurrent': old_matching, 'unmatched_current': unmatched,
        'delete_markers': sum(v['kind'] == 'DeleteMarkers' for v in versions),
        'native_errors': [error], 'diagnosis': diagnosis,
        'capacity': 'unknown', 'progress_clock_trusted': False,
        'rate_actions_per_second': None if measurement is None else measurement['actions'] * 1e9 / measurement['wall_ns'],
        'load_sample': measurement,
    }

